CREATE TABLE IF NOT EXISTS bi_saved_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,report_type VARCHAR(80) NOT NULL,filters JSON NULL,owner_id BIGINT UNSIGNED NULL,is_shared TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bi_alert_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,metric VARCHAR(100) NOT NULL,operator VARCHAR(10) NOT NULL,threshold DECIMAL(18,4) NOT NULL,severity ENUM('info','warning','critical') NOT NULL DEFAULT 'warning',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bi_alert_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rule_id BIGINT UNSIGNED NULL,metric_value DECIMAL(18,4) NULL,message VARCHAR(500) NOT NULL,status ENUM('open','acknowledged','resolved') NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,resolved_at DATETIME NULL,INDEX(rule_id),CONSTRAINT fk_bi_alert_rule FOREIGN KEY(rule_id) REFERENCES bi_alert_rules(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS automation_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,event_name VARCHAR(100) NOT NULL,conditions_json JSON NULL,actions_json JSON NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,last_run_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS automation_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rule_id BIGINT UNSIGNED NULL,status ENUM('success','failed','skipped') NOT NULL,event_payload JSON NULL,result_message VARCHAR(500) NULL,started_at DATETIME NOT NULL,finished_at DATETIME NULL,INDEX(rule_id),CONSTRAINT fk_automation_rule FOREIGN KEY(rule_id) REFERENCES automation_rules(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bi_report_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,report_type VARCHAR(80) NOT NULL,filters JSON NULL,requested_by BIGINT UNSIGNED NULL,file_path VARCHAR(500) NULL,status ENUM('queued','running','completed','failed') NOT NULL DEFAULT 'queued',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO bi_alert_rules(name,metric,operator,threshold,severity,is_active) SELECT 'Overdue invoices','overdue_invoices','>',0,'warning',1 WHERE NOT EXISTS(SELECT 1 FROM bi_alert_rules WHERE metric='overdue_invoices');
INSERT INTO bi_alert_rules(name,metric,operator,threshold,severity,is_active) SELECT 'Open SLA risks','sla_risks','>',0,'critical',1 WHERE NOT EXISTS(SELECT 1 FROM bi_alert_rules WHERE metric='sla_risks');